// Simulador del ESP32 físico (BME280 + ENS160 + BH1750 + SDS011)
// Publica con el formato del diccionario de datos (docs/diccionario_datos_mqtt_tfm.xlsx)
const NODOS = [
    { id: "nodo_sim_1", zone: "zona_norte" },
    { id: "nodo_sim_2", zone: "zona_sur" }
];
const CICLO_SDS011 = 3;   // el SDS011 mide 1 de cada 3 envíos (resto en reposo)

let ciclo = (context.get("ciclo") || 0) + 1;
context.set("ciclo", ciclo);
const arranque = context.get("arranque") || Date.now();
context.set("arranque", arranque);
const segundosEncendido = (Date.now() - arranque) / 1000;

const r = (min, max, dec = 1) => Number((Math.random() * (max - min) + min).toFixed(dec));

return [NODOS.map(n => {
    const sensors = {
        temperature_c: r(19, 28),
        humidity_pct: r(35, 65),
        pressure_hpa: r(1005, 1022),
        eco2_ppm: Math.round(r(450, 1300, 0)),
        tvoc_ppb: Math.round(r(20, 400, 0)),
        aqi: Math.round(r(1, 4, 0)),
        ens160_status: segundosEncendido < 180 ? "warmup" : "ok",
        light_lux: Math.round(r(150, 900, 0))
    };
    if (ciclo % CICLO_SDS011 === 0) {
        sensors.pm25_ugm3 = r(3, 30);
        sensors.pm10_ugm3 = r(8, 60);
    }
    return {
        topic: `tfm/ambiental/${n.zone}/${n.id}/telemetria`,
        payload: JSON.stringify({
            device_id: n.id,
            zone: n.zone,
            timestamp: Math.floor(Date.now() / 1000),
            sensors
        })
    };
})];
